-- ========================================================

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程


local QuestUtils = import('Game.DreamSpace.Quest.QuestUtils')
---@type LuaParametersReader
local LuaParametersReader = import('Game.Utils.LuaParametersReader')

---@type DreamSpaceStates
local DreamSpaceStates = import('Game.DreamSpace.Tools.DreamSpaceStates')

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Canvas = CS.UnityEngine.Canvas
local Transform = CS.UnityEngine.Transform
local Button = CS.UnityEngine.UI.Button
local RectTransform = CS.UnityEngine.RectTransform
local Vector3 = CS.UnityEngine.Vector3
local Quaternion = CS.UnityEngine.Quaternion
local Color = CS.UnityEngine.Color
local Time = CS.UnityEngine.Time
local Text = CS.UnityEngine.UI.Text
local Image = CS.UnityEngine.UI.Image
local Animation = CS.UnityEngine.Animation
local Animator = CS.UnityEngine.Animator


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local LuaParameters = CS.Engine.Modules.LuaParameters

---@type DreamSpaceSounds
local DreamSpaceSounds = import('Game.DreamSpace.Tools.DreamSpaceSounds'):GetInstance()


-- ========================================================

local Default           = "ActionDreamlandMainTask_Default"
local AccomplishGo      = "ActionDreamlandMainTask_AccomplishGo" -- 旧的 task 打勾
local AccomplishHide    = "ActionDreamlandMainTask_AccomplishHide" -- 打勾的 旧 task 消失
local Switch            = "ActionDreamlandMainTask_Switch" -- 从无 到显示 新 task
local Shiny             = "ActionDreamlandMainTask_Shiny" --点击任务图标后高亮左上角任务信息

local currentInstance = nil

-- ========================================================

function UIMain_TaskPanel:__init()
    self.controller = nil
end


function UIMain_TaskPanel:__delete()
end



function UIMain_TaskPanel:Awake()
    if currentInstance == nil then 
        currentInstance = self
    else 
        assert( false, "不允许存在 第二个 UIMain_TaskPanel 实例" )
    end 
end


function UIMain_TaskPanel:Start()
    KTool.SetActive(self.controller.gameObject, true)

    assert( self.taskAnimation and self.finishGroup and self.newGroup and self.tick and self.textComp )

    -- self.finishGroup.gameObject:SetActive( true )
    -- self.newGroup.gameObject:SetActive( true )
    -- self.tick.gameObject:SetActive( true )
    KTool.SetActive( self.finishGroup.gameObject, true )
    KTool.SetActive( self.newGroup.gameObject, true )
    KTool.SetActive( self.tick.gameObject, true )

    self.taskAnimation:Play( Default )
end




function UIMain_TaskPanel:OnDestroy()
    currentInstance = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end



function UIMain_TaskPanel.WaitInstance()
    -- 只等待有限帧
    for i=1, DreamSpaceStates.DelayInitWaitFrames do 
        if isNotNull(currentInstance) then 
            break
        end 
        coroutine.yield(Yielders.EndOfFrame)
    end 
    assert( isNotNull(currentInstance), "始终没能等到 UIMain_TaskPanel 实例化, 请检查场景" )
end


function UIMain_TaskPanel.GetInstance()
    return currentInstance
end

-- =========================================== Self ================================================ --


-- function UIMain_TaskPanel:ShowFstTask(txt_)
