--     self.textComp.text = txt_
-- end


function UIMain_TaskPanel:ShowTick()
    -- 显示 打勾:
    self.taskAnimation:Play( AccomplishGo )
    DreamSpaceSounds.Play( DreamSpaceSounds.sfx.taskComplete )
    while self.taskAnimation.isPlaying == true do
        coroutine.yield(Yielders.EndOfFrame)
    end
end



function UIMain_TaskPanel:HideOldTask()
    -- 旧 task 消失:
    self.taskAnimation:Play( AccomplishHide )
    while self.taskAnimation.isPlaying == true do
        coroutine.yield(Yielders.EndOfFrame)
    end
    self.textComp.text = ""
end


function UIMain_TaskPanel:ShowNewTask(txt_)

    -- 显示新的 task
    self.textComp.text = ""
    self.taskAnimation:Play( Switch )
    while self.taskAnimation.isPlaying == true do
        coroutine.yield(Yielders.EndOfFrame)
    end
    self.textComp.text = txt_
end

function UIMain_TaskPanel:Shiny()
    self.taskAnimation:Play( Shiny )
end

function UIMain_TaskPanel:Activate()
    KTool.SetActive(self.normalGroup, true)
end



return UIMain_TaskPanel

